from copy import deepcopy


def register_entries(store, entries):
    if not isinstance(store, dict):
        raise ValueError("store must be a mapping")
    items = store.get("items")
    next_id = store.get("next_id")
    if not isinstance(items, list):
        raise ValueError("store items must be a list")
    if not isinstance(next_id, int) or isinstance(next_id, bool) or next_id <= 0:
        raise ValueError("next_id must be a positive integer")

    try:
        candidates = list(entries)
    except TypeError as exc:
        raise ValueError("entries must be iterable") from exc

    validated = []
    for entry in candidates:
        if not isinstance(entry, dict) or "label" not in entry or "due_day" not in entry:
            raise ValueError("invalid entry")
        label = entry["label"]
        due_day = entry["due_day"]
        if not isinstance(label, str) or not label.strip():
            raise ValueError("label must be non-empty")
        if not isinstance(due_day, int) or isinstance(due_day, bool) or due_day < 0:
            raise ValueError("due_day must be non-negative")
        validated.append((label.strip(), due_day))

    result = deepcopy(store)
    for offset, (label, due_day) in enumerate(validated):
        result["items"].append({"id": next_id + offset, "label": label, "due_day": due_day})
    result["next_id"] = next_id + len(validated)
    result["all_items"] = result["items"][:]
    return result

